Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

// Dependency: swap implementation
void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

// Target function: partition
int partition (int arr[], int low, int high)
{
    int pivot = arr[high];
    int i = low - 1;

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return i + 1;
}

void setUp(void) { }
void tearDown(void) { }

void test_partition_no_elements_in_loop(void) {
    // Path: loop is not entered (low == high)
    int arr[1] = {42};
    int expected[1] = {42};
    int ret = partition(arr, 0, 0);
    TEST_ASSERT_EQUAL_INT(0, ret);
    TEST_ASSERT_EQUAL_INT(expected[0], arr[0]);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(test_partition_no_elements_in_loop);
    return UNITY_END();
}

